1	// Package funcs contains the template function namespaces.
2	//
3	// Each namespace lives in its own file and self-registers in init() via
4	// RegisterNS (for `ns.Func` style access) and/or RegisterGlobal (for
5	// top-level template functions like `json` or `add`).
6	//
7	// DO NOT change the registration API - other files depend on it.
8	package funcs
9	
10	import (
11		"context"
12		"text/template"
13	)
14	
15	// Deps carries runtime dependencies available to function namespaces.
16	type Deps struct {
17		Ctx          context.Context
18		Data         DataProvider
19		Templates    TemplateRenderer
20		Experimental bool
21	}
22	
23	// DataProvider is implemented by the core datasource registry.
24	type DataProvider interface {
25		// Datasource reads and parses a datasource, optionally with extra
26		// path arguments appended to the source URL.
27		Datasource(alias string, args ...string) (interface{}, error)
28		// Include reads a datasource and returns its raw content as a string.
29		Include(alias string, args ...string) (string, error)
30		// DefineDatasource defines a datasource at runtime; returns the alias.
31		DefineDatasource(alias, rawurl string) (string, error)
32		// DatasourceExists reports whether the alias is defined.
33		DatasourceExists(alias string) bool
34	}
35	
36	// TemplateRenderer renders nested/inline templates with the full function
37	// set available.
38	type TemplateRenderer interface {
39		// RenderInline renders a template given as a string.
40		RenderInline(name, text string, tctx interface{}) (string, error)
41		// RenderPath renders template(s) loaded from a file or directory path.
42		RenderPath(name, path string, tctx interface{}) (string, error)
43		// RenderExec executes a previously-defined template by name.
44		RenderExec(name string, tctx interface{}) (string, error)
45	}
46	
47	// NSFactory creates the object backing a namespace. The returned object's
48	// exported methods become the namespace's functions.
49	type NSFactory func(deps *Deps) interface{}
50	
51	var (
52		namespaces = map[string]NSFactory{}
53		globals    = template.FuncMap{}
54	)
55	
56	// RegisterNS registers a namespace factory under a name, e.g. "strings".
57	func RegisterNS(name string, factory NSFactory) {
58		if _, dup := namespaces[name]; dup {
59			panic("duplicate namespace registration: " + name)
60		}
61		namespaces[name] = factory
62	}
63	
64	// RegisterGlobal registers a top-level template function.
65	func RegisterGlobal(name string, fn interface{}) {
66		if _, dup := globals[name]; dup {
67			panic("duplicate global registration: " + name)
68		}
69		globals[name] = fn
70	}
71	
72	// Build assembles the full template.FuncMap for one render.
73	func Build(deps *Deps) template.FuncMap {
74		fm := template.FuncMap{}
75		for name, f := range namespaces {
76			factory := f
77			fm[name] = func() interface{} { return factory(deps) }
78		}
79		for name, fn := range globals {
80			fm[name] = fn
81		}
82		return fm
83	}

