1	// Package data implements datasource registration and reading.
2	package data
3	
4	import (
5		"context"
6		"fmt"
7		"io"
8		"net/http"
9		"net/url"
10		"os"
11		"path/filepath"
12		"sort"
13		"strings"
14		"sync"
15	
16		"github.com/reimpl/gomplate/internal/dataparse"
17	)
18	
19	// Source is a single registered datasource.
20	type Source struct {
21		Alias  string
22		URL    *url.URL
23		Header http.Header
24	}
25	
26	// Registry holds all defined datasources.
27	type Registry struct {
28		mu       sync.Mutex
29		sources  map[string]*Source
30		headers  map[string]http.Header
31		stdin    io.Reader
32		stdinBuf []byte
33		client   *http.Client
34		cache    map[string]interface{}
35	}
36	
37	func NewRegistry(stdin io.Reader) *Registry {
38		return &Registry{
39			sources: map[string]*Source{},
40			headers: map[string]http.Header{},
41			stdin:   stdin,
42			client:  &http.Client{},
43			cache:   map[string]interface{}{},
44		}
45	}
46	
47	// Define parses a datasource definition of the form "alias=URL", "alias=",
48	// or a bare URL (alias inferred). Returns the alias.
49	func (r *Registry) Define(def string) (string, error) {
50		return r.DefineWithHeader(def, nil)
51	}
52	
53	func (r *Registry) DefineWithHeader(def string, header http.Header) (string, error) {
54		alias, rawurl, ok := strings.Cut(def, "=")
55		if !ok {
56			// no '=' - the whole thing is a URL; infer alias
57			rawurl = def
58			alias = ""
59		}
60		if alias == "" {
61			alias = inferAlias(rawurl)
62			if alias == "" {
63				return "", fmt.Errorf("could not infer datasource alias from %q", def)
64			}
65		}
66		u, err := parseSourceURL(rawurl)
67		if err != nil {
68			return "", fmt.Errorf("invalid datasource URL %q: %v", rawurl, err)
69		}
70		if old, dup := r.sources[alias]; dup {
71			_ = old
72			// later definitions override earlier ones
73		}
74		r.sources[alias] = &Source{Alias: alias, URL: u, Header: header}
75		return alias, nil
76	}
77	
78	// DefineURL defines a datasource from an already-split alias and URL string.
79	func (r *Registry) DefineURL(alias, rawurl string, header http.Header) error {
80		u, err := parseSourceURL(rawurl)
81		if err != nil {
82			return fmt.Errorf("invalid datasource URL %q: %v", rawurl, err)
83		}
84		r.sources[alias] = &Source{Alias: alias, URL: u, Header: header}
85		return nil
86	}
87	
88	func inferAlias(rawurl string) string {
89		// only for plain relative filenames in the current directory
90		if strings.ContainsAny(rawurl, "/:") {
91			return ""
92		}
93		base := filepath.Base(rawurl)
94		ext := filepath.Ext(base)
95		return strings.TrimSuffix(base, ext)
96	}
97	
98	func parseSourceURL(rawurl string) (*url.URL, error) {
99		if rawurl == "" {
100			return &url.URL{}, nil
101		}
102		u, err := url.Parse(rawurl)
103		if err != nil {
104			return nil, err
105		}
106		// bare relative paths (no scheme) are file URLs
107		if u.Scheme == "" {
108			u = &url.URL{Scheme: "file", Path: rawurl}
109			if strings.HasPrefix(rawurl, "/") {
110				u = &url.URL{Scheme: "file", Path: rawurl}
111			}
112		}
113		return u, nil
114	}
115	
116	// AddExtraHeader records headers to send for the given datasource alias.
117	func (r *Registry) AddExtraHeader(alias string, h http.Header) {
118		r.headers[alias] = h
119	}
120	
121	// Exists reports whether a datasource alias is defined.
122	func (r *Registry) Exists(alias string) bool {
123		_, ok := r.sources[alias]
124		return ok
125	}
126	
127	// Aliases returns sorted defined aliases.
128	func (r *Registry) Aliases() []string {
129		out := make([]string, 0, len(r.sources))
130		for a := range r.sources {
131			out = append(out, a)
132		}
133		sort.Strings(out)
134		return out
