143	func (r *Registry) lookup(alias string) (*Source, error) {
144		r.mu.Lock()
145		defer r.mu.Unlock()
146		s, ok := r.sources[alias]
147		if !ok {
148			return nil, fmt.Errorf("undefined datasource '%s'", alias)
149		}
150		return s, nil
