153	// subPath appends extra path args to the source URL.
154	func subPath(u *url.URL, args ...string) *url.URL {
155		v := *u
156		if len(args) > 0 && args[0] != "" {
157			p := strings.Join(args, "/")
158			base := v.Path
159			if v.Opaque != "" {
160				base = v.Opaque
161			}
162			if strings.HasSuffix(base, "/") {
163				base += p
164			} else if base == "" {
165				base = p
166			} else {
167				base += "/" + p
168			}
169			if v.Opaque != "" {
170				v.Opaque = base
171			} else {
172				v.Path = base
173			}
174		}
175		return &v
176	}
177	
178	// Datasource reads and parses a datasource.
179	func (r *Registry) Datasource(ctx context.Context, alias string, args ...string) (interface{}, error) {
180		s, err := r.lookup(alias)
181		if err != nil {
182			return nil, err
183		}
184		u := subPath(s.URL, args...)
185		key := alias + "|" + u.String()
186		if v, ok := r.cache[key]; ok {
187			return v, nil
188		}
189		v, err := r.read(ctx, s, u, false)
190		if err != nil {
191			return nil, err
192		}
193		r.cache[key] = v
194		return v, nil
195	}
196	
197	// Include reads a datasource and returns raw string content.
198	func (r *Registry) Include(ctx context.Context, alias string, args ...string) (string, error) {
199		s, err := r.lookup(alias)
200		if err != nil {
201			return "", err
202		}
203		u := subPath(s.URL, args...)
204		v, err := r.read(ctx, s, u, true)
205		if err != nil {
206			return "", err
207		}
208		return v.(string), nil
209	}
