211	// read fetches content. If raw is true, returns the content as string.
212	func (r *Registry) read(ctx context.Context, s *Source, u *url.URL, raw bool) (interface{}, error) {
213		scheme := u.Scheme
214		switch scheme {
215		case "file", "":
216			return r.readFile(u, raw)
217		case "stdin":
218			return r.readStdin(u, raw)
219		case "env":
220			return r.readEnv(u, raw)
221		case "http", "https":
222			return r.readHTTP(ctx, s, u, raw)
223		case "merge":
224			return r.readMerge(ctx, s, u, raw)
225		default:
226			return nil, fmt.Errorf("datasources with scheme %q are not supported", scheme)
227		}
228	}
