230	func mimeOverride(u *url.URL) string {
231		param := os.Getenv("GOMPLATE_TYPE_PARAM")
232		if param == "" {
233			param = "type"
234		}
235		q := u.Query()
236		t := q.Get(param)
237		if i := strings.IndexByte(t, ';'); i >= 0 {
238			t = strings.TrimSpace(t[:i])
239		}
240		return t
241	}
242	
243	var extMimes = map[string]string{
244		".json": "application/json",
245		".yml":  "application/yaml",
246		".yaml": "application/yaml",
247		".toml": "application/toml",
248		".csv":  "text/csv",
249		".env":  "application/x-env",
250	}
251	
252	func mimeFor(u *url.URL, httpMime string) string {
253		if t := mimeOverride(u); t != "" {
254			return t
255		}
256		if httpMime != "" {
257			if i := strings.IndexByte(httpMime, ';'); i >= 0 {
258				httpMime = strings.TrimSpace(httpMime[:i])
259			}
260			if m, ok := extMimes[strings.ToLower(filepath.Ext(u.Path))]; ok && httpMime == "text/plain" {
261				return m
262			}
263			return httpMime
264		}
265		ext := strings.ToLower(filepath.Ext(u.Path))
266		if m, ok := extMimes[ext]; ok {
267			return m
268		}
269		return "text/plain"
270	}
271	
272	// parseContent parses bytes per MIME type.
273	func parseContent(mime string, b []byte) (interface{}, error) {
274		switch mime {
275		case "application/json":
276			return dataparse.JSON(b)
277		case "application/array+json":
278			return dataparse.JSONArray(b)
279		case "application/yaml", "application/x-yaml", "text/yaml":
280			if dataparse.YAML == nil {
281				return nil, fmt.Errorf("YAML support unavailable")
282			}
283			return dataparse.YAML(b)
284		case "application/toml":
285			if dataparse.TOML == nil {
286				return nil, fmt.Errorf("TOML support unavailable")
287			}
288			return dataparse.TOML(b)
289		case "text/csv":
290			return dataparse.CSV(0, b)
291		case "application/x-env":
292			return dataparse.EnvFile(b)
293		case "text/plain", "application/octet-stream", "":
294			return string(b), nil
295		default:
296			return nil, fmt.Errorf("unsupported MIME type: %s", mime)
297		}
298	}
