300	func (r *Registry) readFile(u *url.URL, raw bool) (interface{}, error) {
301		path := u.Path
302		if u.Host != "" && u.Host != "." {
303			path = u.Host + u.Path
304		}
305		if strings.HasSuffix(u.Path, "/") {
306			entries, err := os.ReadDir(path)
307			if err != nil {
308				return nil, err
309			}
310			names := []string{}
311			for _, e := range entries {
312				names = append(names, e.Name())
313			}
314			return names, nil
315		}
316		b, err := os.ReadFile(path)
317		if err != nil {
318			return nil, err
319		}
320		if raw {
321			return string(b), nil
322		}
323		return parseContent(mimeFor(u, ""), b)
324	}
325	
326	func (r *Registry) readStdin(u *url.URL, raw bool) (interface{}, error) {
327		r.mu.Lock()
328		if r.stdinBuf == nil {
329			b, err := io.ReadAll(r.stdin)
330			if err != nil {
331				r.mu.Unlock()
332				return nil, err
333			}
334			r.stdinBuf = b
335		}
336		b := r.stdinBuf
337		r.mu.Unlock()
338		if raw {
339			return string(b), nil
340		}
341		return parseContent(mimeFor(u, ""), b)
342	}
343	
344	func (r *Registry) readEnv(u *url.URL, raw bool) (interface{}, error) {
345		name := u.Opaque
346		if name == "" {
347			name = strings.TrimLeft(u.Path, "/")
348		}
349		val := os.Getenv(name)
350		if raw {
351			return val, nil
352		}
353		return parseContent(mimeFor(u, ""), []byte(val))
354	}
355	
356	func (r *Registry) readHTTP(ctx context.Context, s *Source, u *url.URL, raw bool) (interface{}, error) {
357		req, err := http.NewRequestWithContext(ctx, http.MethodGet, u.String(), nil)
358		if err != nil {
359			return nil, err
360		}
361		req.Header.Set("User-Agent", "Go-http-client/1.1")
362		for k, vs := range s.Header {
363			for _, v := range vs {
364				req.Header.Set(k, v)
365			}
366		}
367		if h, ok := r.headers[s.Alias]; ok {
368			for k, vs := range h {
369				for _, v := range vs {
370					req.Header.Set(k, v)
371				}
372			}
373		}
374		resp, err := r.client.Do(req)
375		if err != nil {
376			return nil, err
377		}
378		defer resp.Body.Close()
379		b, err := io.ReadAll(resp.Body)
380		if err != nil {
381			return nil, err
382		}
383		if resp.StatusCode < 200 || resp.StatusCode > 299 {
384			return nil, fmt.Errorf("unexpected HTTP status %d from %s", resp.StatusCode, u.String())
385		}
386		if raw {
387			return string(b), nil
388		}
389		return parseContent(mimeFor(u, resp.Header.Get("Content-Type")), b)
390	}
391	
392	func (r *Registry) readMerge(ctx context.Context, s *Source, u *url.URL, raw bool) (interface{}, error) {
393		parts := strings.Split(u.Opaque, "|")
394		if len(parts) < 2 {
395			return nil, fmt.Errorf("merge: requires at least two datasources")
396		}
397		var merged map[string]interface{}
398		// merge right to left
399		for i := len(parts) - 1; i >= 0; i-- {
400			p := parts[i]
401			var v interface{}
402			var err error
403			if r.Exists(p) {
404				v, err = r.Datasource(ctx, p)
405			} else {
406				tmp := &Source{Alias: p}
407				tu, terr := parseSourceURL(p)
408				if terr != nil {
409					return nil, terr
410				}
411				v, err = r.read(ctx, tmp, tu, false)
412			}
413			if err != nil {
414				return nil, err
415			}
416			m, ok := v.(map[string]interface{})
417			if !ok {
418				return nil, fmt.Errorf("merge: datasource %q is not a map", p)
419			}
420			merged = deepMerge(m, merged)
421		}
422		return merged, nil
423	}
424	
425	// deepMerge overlays src onto dst (src wins), merging nested maps.
426	func deepMerge(src, dst map[string]interface{}) map[string]interface{} {
427		if dst == nil {
428			dst = map[string]interface{}{}
429		}
430		for k, v := range src {
431			if sm, ok := v.(map[string]interface{}); ok {
432				if dm, ok := dst[k].(map[string]interface{}); ok {
433					dst[k] = deepMerge(sm, dm)
434					continue
435				}
436			}
437			dst[k] = v
438		}
439		return dst
440	}

