32	// Run executes gomplate. Returns the exit code.
33	func Run(args []string, stdin io.Reader, stdout, stderr *os.File) int {
34		log := newLogger(stderr)
35	
36		fv, postExec, err := parseFlags(args)
37		if err != nil {
38			fmt.Fprintf(stderr, "Error: %s\n", err)
39			fmt.Fprint(stdout, usageText)
40			if os.Getenv("GOMPLATE_LOG_FORMAT") != "" {
41				log.ErrorMsg(err.Error())
42			} else {
43				fmt.Fprintf(stderr, "ERROR  err=%q\n", err.Error())
44			}
45			return 1
46		}
47		if fv.bools["help"] {
48			fmt.Fprint(stdout, helpText)
49			return 0
50		}
51		if fv.bools["version"] {
52			fmt.Fprintln(stdout, versionString)
53			return 0
54		}
55	
56		cfg, cerr := loadConfig(fv, postExec)
57		if cerr != nil {
58			log.Error(cerr)
59			return 1
60		}
61		log.verbose = cfg.Verbose
62	
63		if err := cfg.validate(); err != nil {
64			log.ErrorMsg("failed to validate config: " + err.Error())
65			return 1
66		}
67	
68		r := &renderer{
69			cfg:     cfg,
70			sources: data.NewRegistry(stdin),
71			stdin:   stdin,
72			stdout:  stdout,
73			stderr:  stderr,
74			log:     log,
75		}
76	
77		// register datasources
78		for alias, sc := range cfg.Datasources {
79			if alias == "" {
80				if _, err := r.sources.DefineWithHeader(sc.URL, sc.Header); err != nil {
81					log.Error(err)
82					return 1
83				}
84				continue
85			}
86			if err := r.sources.DefineURL(alias, sc.URL, sc.Header); err != nil {
87				log.Error(err)
88				return 1
89			}
90		}
91		for alias, sc := range cfg.Context {
92			if alias != "" {
93				if err := r.sources.DefineURL(alias, sc.URL, sc.Header); err != nil {
94					log.Error(err)
95					return 1
96				}
97			}
98		}
99	
100		r.deps = &funcs.Deps{
101			Ctx:          context.Background(),
102			Data:         &dataProvider{r: r},
103			Experimental: cfg.Experimental,
104		}
105		r.deps.Templates = r
106	
107		// build the default context
108		tctx, err := r.buildContext()
109		if err != nil {
110			log.Error(err)
111			return 1
112		}
113		r.tctx = tctx
114	
115		templates, err := r.gatherTemplates()
116		if err != nil {
117			log.ErrorMsg("failed to gather templates for rendering: " + err.Error())
118			return 1
119		}
120	
121		var lastOutput bytes.Buffer
122		for _, t := range templates {
123			out, rerr := r.renderOne(t)
124			if rerr != nil {
125				log.ErrorMsg("renderTemplate: " + rerr.Error())
126				return 1
127			}
128			lastOutput.Reset()
129			lastOutput.Write(out)
130			if cfg.ExecPipe {
131				continue
132			}
133			if werr := r.writeOutput(t, out); werr != nil {
134				log.Error(werr)
135				return 1
136			}
137		}
138	
139		if len(cfg.PostExec) > 0 {
140			if err := r.runPostExec(&lastOutput); err != nil {
141				log.Error(err)
142				return 1
143			}
144		}
145		return 0
146	}
