148	// loadConfig merges defaults, env, config file, and flags.
149	func loadConfig(fv *flagValues, postExec []string) (*config, error) {
150		cfg := defaultConfig()
151		cfg.applyEnv()
152	
153		cfgPath := fv.strings["config"]
154		if !fv.changed["config"] {
155			cfgPath = os.Getenv("GOMPLATE_CONFIG")
156			if cfgPath == "" {
157				if _, ok := os.LookupEnv("GOMPLATE_CONFIG"); !ok {
158					cfgPath = ".gomplate.yaml"
159				}
160			}
161		}
162		if cfgPath != "" {
163			b, err := os.ReadFile(cfgPath)
164			switch {
165			case err == nil:
166				if dataparse.YAML == nil {
167					return nil, fmt.Errorf("failed to read config file: YAML support unavailable")
168				}
169				v, err := dataparse.YAML(b)
170				if err != nil {
171					return nil, fmt.Errorf("failed to parse config file %s: %v", cfgPath, err)
172				}
173				if m, ok := v.(map[string]interface{}); ok {
174					if err := cfg.applyMap(m); err != nil {
175						return nil, fmt.Errorf("failed to parse config file %s: %v", cfgPath, err)
176					}
177				}
178			case cfgPath != ".gomplate.yaml" || fv.changed["config"]:
179				if !os.IsNotExist(err) {
180					return nil, fmt.Errorf("failed to read config file %s: %v", cfgPath, err)
181				}
182				if fv.changed["config"] || os.Getenv("GOMPLATE_CONFIG") != "" {
183					return nil, fmt.Errorf("failed to read config file %s: %v", cfgPath, err)
184				}
185			}
186		}
187	
188		cfg.applyFlags(fv)
189		if len(postExec) > 0 {
190			cfg.PostExec = postExec
191		}
192		if cfg.Input != "" {
193			cfg.InputFiles = nil
194		}
195		return cfg, nil
196	}
