229	// buildContext constructs the default template context.
230	func (r *renderer) buildContext() (interface{}, error) {
231		env := map[string]string{}
232		for _, e := range os.Environ() {
233			k, v, _ := strings.Cut(e, "=")
234			env[k] = v
235		}
236		var root map[string]interface{} = map[string]interface{}{"Env": env}
237	
238		// aliases in deterministic order: "." first
239		aliases := make([]string, 0, len(r.cfg.Context))
240		for a := range r.cfg.Context {
241			aliases = append(aliases, a)
242		}
243		if i := indexOf(aliases, "."); i > 0 {
244			aliases[0], aliases[i] = aliases[i], aliases[0]
245		}
246		for _, alias := range aliases {
247			sc := r.cfg.Context[alias]
248			v, err := r.sources.Datasource(r.deps.Ctx, alias)
249			if err != nil {
250				return nil, fmt.Errorf("failed to load context datasource %s (%s): %v", alias, sc.URL, err)
251			}
252			if alias == "." {
253				if m, ok := v.(map[string]interface{}); ok {
254					root = m
255				} else {
256					root = map[string]interface{}{"": v}
257					return v, nil
258				}
259			} else {
260				root[alias] = v
261			}
262		}
263		return root, nil
264	}
