292	// parseNested adds --template templates to the template set.
293	func (r *renderer) parseNested(t *template.Template) error {
294		for alias, sc := range r.cfg.Templates {
295			path := sc.URL
296			path = strings.TrimPrefix(path, "file://")
297			fi, err := os.Stat(path)
298			if err != nil {
299				return fmt.Errorf("stat %q: %w", path, err)
300			}
301			if fi.IsDir() || strings.HasSuffix(sc.URL, "/") {
302				entries, err := os.ReadDir(path)
303				if err != nil {
304					return err
305				}
306				for _, e := range entries {
307					if e.IsDir() {
308						continue
309					}
310					b, err := os.ReadFile(filepath.Join(path, e.Name()))
311					if err != nil {
312						return err
313					}
314					name := filepath.Join(alias, e.Name())
315					if alias == "" {
316						name = filepath.Join(path, e.Name())
317					}
318					if _, err := t.New(name).Parse(string(b)); err != nil {
319						return fmt.Errorf("parse template %s: %w", name, err)
320					}
321				}
322				continue
323			}
324			b, err := os.ReadFile(path)
325			if err != nil {
326				return err
327			}
328			name := alias
329			if name == "" {
330				name = sc.URL
331			}
332			if _, err := t.New(name).Parse(string(b)); err != nil {
333				return fmt.Errorf("parse template %s: %w", name, err)
334			}
335		}
336		return nil
337	}
