363	// RenderInline implements funcs.TemplateRenderer.
364	func (r *renderer) RenderInline(name, text string, tctx interface{}) (string, error) {
365		t := r.newTemplate(name)
366		tmpl, err := t.Parse(text)
367		if err != nil {
368			return "", fmt.Errorf("parse template %s: %w", name, err)
369		}
370		buf := &bytes.Buffer{}
371		if err := tmpl.ExecuteTemplate(buf, name, tctx); err != nil {
372			return "", fmt.Errorf("failed to render template %s: %w", name, err)
373		}
374		return buf.String(), nil
375	}
