377	// RenderPath implements funcs.TemplateRenderer.
378	func (r *renderer) RenderPath(name, path string, tctx interface{}) (string, error) {
379		fi, err := os.Stat(path)
380		if err != nil {
381			return "", fmt.Errorf("stat %q: %w", path, err)
382		}
383		t := r.newTemplate(name)
384		execName := name
385		if fi.IsDir() {
386			entries, err := os.ReadDir(path)
387			if err != nil {
388				return "", err
389			}
390			for _, e := range entries {
391				if e.IsDir() {
392					continue
393				}
394				b, err := os.ReadFile(filepath.Join(path, e.Name()))
395				if err != nil {
396					return "", err
397				}
398				if _, err := t.New(e.Name()).Parse(string(b)); err != nil {
399					return "", fmt.Errorf("parse template %s: %w", e.Name(), err)
400				}
401			}
402			execName = filepath.Base(path)
403		} else {
404			b, err := os.ReadFile(path)
405			if err != nil {
406				return "", err
407			}
408			if _, err := t.Parse(string(b)); err != nil {
409				return "", fmt.Errorf("parse template %s: %w", name, err)
410			}
411		}
412		buf := &bytes.Buffer{}
413		if err := t.ExecuteTemplate(buf, execName, tctx); err != nil {
414			return "", fmt.Errorf("failed to render template %s: %w", name, err)
415		}
416		return buf.String(), nil
417	}
