432	// tmplInput is one template to render plus its output target.
433	type tmplInput struct {
434		name string // template name (also used in error messages)
435		text string
436		out  string // output path or "-"
437		mode os.FileMode
438	}
439	
440	// gatherTemplates computes the list of templates to render.
441	func (r *renderer) gatherTemplates() ([]tmplInput, error) {
442		cfg := r.cfg
443		switch {
444		case cfg.Input != "":
445			out := "-"
446			if len(cfg.OutputFiles) > 0 && cfg.OutputFiles[0] != "" {
447				out = cfg.OutputFiles[0]
448			}
449			return []tmplInput{{name: "<arg>", text: cfg.Input, out: out, mode: 0o644}}, nil
450	
451		case cfg.InputDir != "":
452			return r.gatherDir()
453	
454		default:
455			inputs := cfg.InputFiles
456			if len(inputs) == 0 {
457				inputs = []string{"-"}
458			}
459			outs := cfg.OutputFiles
460			if len(outs) == 0 {
461				outs = []string{"-"}
462			}
463			var stdinText string
464			var stdinErr error
465			var stdinOnce bool
466			out := make([]tmplInput, 0, len(inputs))
467			for i, in := range inputs {
468				o := "-"
469				if i < len(outs) {
470					o = outs[i]
471				}
472				if in == "-" {
473					if !stdinOnce {
474						b, err := io.ReadAll(r.stdin)
475						stdinText, stdinErr, stdinOnce = string(b), err, true
476					}
477					if stdinErr != nil {
478						return nil, stdinErr
479					}
480					out = append(out, tmplInput{name: "-", text: stdinText, out: o, mode: 0o644})
481					continue
482				}
483				fi, err := os.Stat(in)
484				if err != nil {
485					return nil, fmt.Errorf("fileToTemplate: stat %q: %w", in, err)
486				}
487				b, err := os.ReadFile(in)
488				if err != nil {
489					return nil, fmt.Errorf("fileToTemplate: %w", err)
490				}
491				out = append(out, tmplInput{name: in, text: string(b), out: o, mode: fi.Mode()})
492			}
493			return out, nil
494		}
495	}
