497	// gatherDir handles --input-dir mode.
498	func (r *renderer) gatherDir() ([]tmplInput, error) {
499		cfg := r.cfg
500		root := cfg.InputDir
501		var out []tmplInput
502		ignores, err := loadGomplateIgnores(root)
503		if err != nil {
504			return nil, err
505		}
506		err = filepath.Walk(root, func(path string, fi os.FileInfo, err error) error {
507			if err != nil {
508				return err
509			}
510			rel, err := filepath.Rel(root, path)
511			if err != nil {
512				return err
513			}
514			if fi.IsDir() {
515				return nil
516			}
517			if matchPatterns(ignores, rel) || matchPatterns(cfg.Excludes, rel) {
518				return nil
519			}
520			included := len(cfg.Includes) == 0
521			for _, p := range cfg.Includes {
522				neg := strings.HasPrefix(p, "!")
523				pat := strings.TrimPrefix(p, "!")
524				if matchPatterns([]string{pat}, rel) {
525					included = !neg
526				}
527			}
528			if !included {
529				return nil
530			}
531			outPath := ""
532			copyOnly := matchPatterns(cfg.ExcludeProcessing, rel)
533			if cfg.OutputMap != "" {
534				m, rerr := r.renderOutputMap(rel)
535				if rerr != nil {
536					return rerr
537				}
538				outPath = m
539			} else {
540				outPath = filepath.Join(cfg.OutputDir, rel)
541			}
542			if copyOnly {
543				b, err := os.ReadFile(path)
544				if err != nil {
545					return err
546				}
547				out = append(out, tmplInput{name: path, text: string(b), out: outPath, mode: fi.Mode()})
548				return nil
549			}
550			b, err := os.ReadFile(path)
551			if err != nil {
552				return err
553			}
554			out = append(out, tmplInput{name: path, text: string(b), out: outPath, mode: fi.Mode()})
555			return nil
556		})
557		return out, err
558	}
