560	// renderOutputMap renders the --output-map template for one input file.
561	func (r *renderer) renderOutputMap(rel string) (string, error) {
562		omCtx := map[string]interface{}{
563			"in":  filepath.ToSlash(rel),
564			"ctx": r.tctx,
565		}
566		if m, ok := r.tctx.(map[string]interface{}); ok {
567			for k, v := range m {
568				if k != "in" && k != "ctx" {
569					omCtx[k] = v
570				}
571			}
572		}
573		t := r.newTemplate("<outputMap>")
574		tmpl, err := t.Parse(r.cfg.OutputMap)
575		if err != nil {
576			return "", fmt.Errorf("parse template <outputMap>: %w", err)
577		}
578		buf := &bytes.Buffer{}
579		if err := tmpl.Execute(buf, omCtx); err != nil {
580			return "", fmt.Errorf("failed to render template <outputMap>: %w", err)
581		}
582		return strings.TrimSpace(buf.String()), nil
583	}
