590	// writeOutput writes rendered bytes to the output target.
591	func (r *renderer) writeOutput(t tmplInput, out []byte) error {
592		// empty/whitespace-only output is not written
593		if strings.TrimSpace(string(out)) == "" {
594			return nil
595		}
596		if t.out == "-" || t.out == "" {
597			_, err := r.stdout.Write(out)
598			return err
599		}
600		mode := t.mode
601		if r.cfg.Chmod != "" {
602			m, err := strconv.ParseUint(r.cfg.Chmod, 8, 32)
603			if err != nil {
604				return fmt.Errorf("invalid --chmod value %q: %v", r.cfg.Chmod, err)
605			}
606			mode = os.FileMode(m)
607		}
608		if dir := filepath.Dir(t.out); dir != "" && dir != "." {
609			if err := os.MkdirAll(dir, 0o755); err != nil {
610				return err
611			}
612		}
613		if err := os.WriteFile(t.out, out, mode); err != nil {
614			return err
615		}
616		// ensure mode even if file existed
617		if r.cfg.Chmod != "" {
618			if err := os.Chmod(t.out, mode); err != nil {
619				return err
620			}
621		}
622		return nil
623	}
