625	// runPostExec runs the post-template command.
626	func (r *renderer) runPostExec(out *bytes.Buffer) error {
627		cmd := exec.CommandContext(r.deps.Ctx, r.cfg.PostExec[0], r.cfg.PostExec[1:]...)
628		cmd.Stdout = r.stdout
629		cmd.Stderr = r.stderr
630		if r.cfg.ExecPipe {
631			cmd.Stdin = out
632		}
633		if err := cmd.Run(); err != nil {
634			return fmt.Errorf("failed to run post-exec command: %w", err)
635		}
636		return nil
637	}
