639	// pluginFunc creates a template function that runs an external command.
640	func (r *renderer) pluginFunc(pc pluginConf) interface{} {
641		return func(args ...interface{}) (string, error) {
642			timeout := pc.Timeout
643			if timeout == 0 {
644				timeout = r.cfg.PluginTimeout
645			}
646			ctx, cancel := context.WithTimeout(r.deps.Ctx, timeout)
647			defer cancel()
648	
649			argv := append([]string{}, pc.Args...)
650			var stdinData string
651			strs := make([]string, 0, len(args))
652			for _, a := range args {
653				strs = append(strs, fmt.Sprintf("%v", a))
654			}
655			if pc.Pipe && len(strs) > 0 {
656				stdinData = strs[len(strs)-1]
657				strs = strs[:len(strs)-1]
658			}
659			argv = append(argv, strs...)
660	
661			cmd := exec.CommandContext(ctx, pc.Cmd, argv...)
662			if pc.Pipe {
663				cmd.Stdin = strings.NewReader(stdinData)
664			}
665			cmd.Stderr = r.stderr
666			var outBuf bytes.Buffer
667			cmd.Stdout = &outBuf
668			if err := cmd.Run(); err != nil {
669				return "", fmt.Errorf("plugin %s failed: %w", pc.Cmd, err)
670			}
671			return strings.TrimRight(outBuf.String(), "\n"), nil
672		}
673	}
