675	// --- gitignore-ish pattern matching (simplified) ---
676	
677	func loadGomplateIgnores(root string) ([]string, error) {
678		var patterns []string
679		b, err := os.ReadFile(filepath.Join(root, ".gomplateignore"))
680		if err != nil {
681			return nil, nil
682		}
683		for _, line := range strings.Split(string(b), "\n") {
684			line = strings.TrimSpace(line)
685			if line == "" || strings.HasPrefix(line, "#") {
686				continue
687			}
688			patterns = append(patterns, line)
689		}
690		return patterns, nil
691	}
692	
693	// matchPatterns reports whether rel matches any pattern (with ! negation).
694	func matchPatterns(patterns []string, rel string) bool {
695		rel = filepath.ToSlash(rel)
696		matched := false
697		for _, p := range patterns {
698			neg := strings.HasPrefix(p, "!")
699			pat := strings.TrimPrefix(p, "!")
700			if matchGitignore(pat, rel) {
701				matched = !neg
702			}
703		}
704		return matched
705	}
706	
707	func matchGitignore(pattern, rel string) bool {
708		pattern = strings.TrimPrefix(pattern, "/")
709		if strings.HasSuffix(pattern, "/") {
710			pattern = strings.TrimSuffix(pattern, "/")
711			// directory prefix match
712			if strings.HasPrefix(rel, pattern+"/") || rel == pattern {
713				return true
714			}
715		}
716		if !strings.Contains(pattern, "/") {
717			// match against any path element
718			for _, part := range strings.Split(rel, "/") {
719				if ok, _ := pathMatch(pattern, part); ok {
720					return true
721				}
722			}
723			return false
724		}
725		ok, _ := pathMatch(pattern, rel)
726		return ok
727	}
728	
729	// pathMatch is like path.Match but supports **.
730	func pathMatch(pattern, name string) (bool, error) {
731		px := strings.Split(pattern, "/")
732		nx := strings.Split(name, "/")
733		return matchSegments(px, nx), nil
734	}
735	
736	func matchSegments(px, nx []string) bool {
737		for len(px) > 0 {
738			if px[0] == "**" {
739				// ** matches zero or more segments
740				if len(px) == 1 {
741					return true
742				}
743				for i := 0; i <= len(nx); i++ {
744					if matchSegments(px[1:], nx[i:]) {
745						return true
746					}
747				}
748				return false
749			}
750			if len(nx) == 0 {
751				return false
752			}
753			ok, err := filepath.Match(px[0], nx[0])
754			if err != nil || !ok {
755				return false
756			}
757			px, nx = px[1:], nx[1:]
758		}
759		return len(nx) == 0
760	}

